[
  {
    "id": "claudinite-isolation",
    "severity": "blocking",
    "failureMessage": "the vendored canon is refreshed nightly and refactored upstream — code that reaches into it inherits every canon rename as a breaking change",
    "fix": "inline the few lines you need into your own tree, remove the reference, or accept it with a reason in .claudinite-checks.json (rule \"claudinite-isolation\")",
    "relevantWhen": { "pathExists": ".claudinite/shared" },
    "forbidReferences": [
      {
        "from": ".",
        "to": ".claudinite",
        "matchUniqueFilenames": false,
        "except": [".claudinite", ".claude", ".github/workflows", ".gitignore", ".gitattributes", "CLAUDE.md", ".claudinite-checks.json"],
        "reason": "consumer files must not couple to the vendored canon — the wiring files are the reviewed exceptions (vendoring/DESIGN.md)"
      }
    ]
  }
]

import rulesIndexCurrent from './rules-index-current.mjs';
import coreDeclared from './core-declared.mjs';
import conformanceWorkflow from './conformance-workflow.mjs';
import schedulerWorkflowShape from './scheduler-workflow-shape.mjs';
import taskDeclarationShape from './task-declaration-shape.mjs';
import taskDeclarationMatchesFolder from './task-declaration-matches-folder.mjs';
import taskPhaseDiscipline from './task-phase-discipline.mjs';

// Claudinite's own surface in a repo that runs it: the vendored mount, the
// declaration that activates a pack, adopting Claudinite and adopting a pack,
// and the contract every scheduled task is written to.
//
// EVERY RULE HERE JUDGES A MEMBER'S CLAUDINITE STATUS — is this repo declared,
// converged, gated and scheduled such that Claudinite works in it. Rules about
// how the canon's own content is maintained are not this pack's, however much
// they look like it.
//
// MANDATORY. `basics` requires this pack, which both vendors its content and
// materializes its declaration wherever a declaration is written; the
// migrations/2026-08-14-core-seed record declares it into members that already
// exist. Both run outside any check — activation reads the literal declaration,
// so `core-declared` reports a member that has lost the entry rather than being
// what puts it there.
export default {
  id: 'core',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'using Claudinite itself — the vendored mount, the pack declaration, bootstrapping, adopting packs, the self-refresh update, the scheduled-task contract',
    excludes: 'general working discipline and the task lifecycle — basics; capturing lessons into packs — grow_with_claudinite; git procedure — git-github',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // The consumer-isolation wall (claudinite-isolation) is a declared check — a
  // forbidReferences entry in this pack's declared-checks.json, run by the
  // engine's reference-scanning like any barrier. The barriers pack stays
  // required for the per-repo config rule members' own edges ride.
  requires: ['barriers'],
  worldRules: [
    // The declaration itself, and the index the declaration produces — the two
    // things that decide whether this member is running Claudinite at all.
    coreDeclared,
    rulesIndexCurrent,
    // The member's plumbing — the CI gate its maintenance PR merges through, and
    // the scheduler workflow that fires its tasks. Both relevance-first: inert
    // until the repo carries the artifact.
    conformanceWorkflow,
    schedulerWorkflowShape,
    // The scheduled-task contract (scheduled-tasks.md), likewise inert until the
    // repo carries a tasks/<name>/task.mjs of its own.
    taskDeclarationShape,
    taskDeclarationMatchesFolder,
    taskPhaseDiscipline,
  ],
  workRules: [],
  // Bootstrapping a repo, and adding a pack to one already bootstrapped. Both
  // were bundled in grow_with_claudinite, whose subject is lesson capture.
  skills: [
    'adopt-claudinite',
    'adopt-pack',
  ],
  // The scheduled task that acts on a repo's pack-adoption requests lives in this
  // pack's `tasks/`, discovered by the scheduler's filesystem scan
  // (engine/scheduler/discover.mjs), not declared here.
};

[
  {
    "id": "claude-md-length",
    "severity": "advisory",
    "failureMessage": "everything in CLAUDE.md loads every session; past ~200 lines it crowds out the rules that matter",
    "scanFiles": "CLAUDE.md",
    "maxLines": {
      "limit": 200,
      "what": "{lines} lines (target under {limit})",
      "fix": "move multi-step procedures to skills and part-of-repo rules to path-scoped packs; keep CLAUDE.md to always-true facts"
    }
  },
  {
    "id": "generated-merge-driver",
    "severity": "advisory",
    "failureMessage": "without merge=ours a conflicting merge on a generated file gets hand-resolved and desyncs from its source",
    "requireIndexCoverage": [
      {
        "eachScannedPathMatching": "/(?<base>[^/]*GENERATED[^/]*)$/",
        "includeVendored": true,
        "indexFile": ".gitattributes",
        "coveredByGlobLinesMatching": "/\\bmerge=ours\\b/",
        "whenIndexFileAbsent": "flagEveryPath",
        "anchorFindingsAt": "eachUncoveredPath",
        "what": "a GENERATED file with no merge=ours .gitattributes entry",
        "fix": "add `{base} merge=ours` to .gitattributes (plus a one-time `git config merge.ours.driver true`) so a conflicting merge auto-resolves"
      }
    ]
  },
  {
    "id": "catalog-completeness",
    "severity": "blocking",
    "failureMessage": "a hand-maintained catalog that omits a real pack misroutes readers and hides capability; the check keeps the index honest against the tree",
    "relevantWhen": { "trackedFileMatches": "/^engine\\/pack_loader\\/pack-registry\\.mjs$/" },
    "requireIndexCoverage": [
      {
        "eachTrackedPathMatching": "/^packs\\/(?<name>[^/]+)\\/pack\\.mjs$/",
        "indexFile": "packs/README.md",
        "coveredByText": "({name}/",
        "whenIndexFileAbsent": "assertNothing",
        "anchorFindingsAt": "indexFile",
        "what": "the pack \"{name}\" exists on disk but is not listed in packs/README.md",
        "fix": "add a \"{name}\" entry to packs/README.md (or delete the pack if it is dead)"
      }
    ]
  }
]

import commentClassification from './comment-classification.mjs';
import referenceIntegrity from './reference-integrity.mjs';
import markdownLinkLabels from './markdown-link-labels.mjs';
import taskLifecycle from './task-lifecycle.mjs';
import warningSuppression from './warning-suppression.mjs';
import filePlacement from './file-placement.mjs';
import squashMergeHistory from './squash-merge-history.mjs';
import sharedConstants from './shared-constants.mjs';
import rulesLineLength from './rules-line-length.mjs';
import declaredCheckMessages from './declared-check-messages.mjs';

// The baseline pack: cross-project working discipline, the task lifecycle, and
// the general engineering skills. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly update
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
export default {
  id: 'basics',
  // 2 — the mechanism rename (migrations/2026-08-13-mechanism-versioned). The FIRST
  // bump this pack has taken, and the invariant it establishes: a record's declared
  // `version` must be ≤ this number, and this number must MOVE for that record to
  // reach a member already at the previous one. `migrationApplies` is `want > have`
  // against the stamped version, and what gets stamped is this manifest's number — so
  // a record declaring a version above it would re-apply every cycle, forever,
  // draining never.
  version: 2,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'cross-project working discipline, issue-branch-PR lifecycle, repo hygiene, doc/reference integrity and the baseline engineering, testing and debugging skills',
    excludes: 'technology-specific content — its own tech pack; GitHub Actions workflow or platform behaviour — github-actions; git procedure — git-github',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // `core` is required rather than assumed: this pack is declared everywhere, so
  // the closure is what puts Claudinite's own rules in front of every session, and
  // `barriers` arrives with it. git-github carries the git/GitHub side of the task
  // lifecycle (#385).
  requires: ['core', 'git-github'],
  // Rules that audit the repo as it stands, whatever this session did.
  worldRules: [
    markdownLinkLabels,
    rulesLineLength,
    declaredCheckMessages,
    warningSuppression,
    filePlacement,
    sharedConstants,
  ],
  // Rules that judge the change and the session in front of you — the branch's
  // commits, the diff, the conversation.
  workRules: [
    commentClassification,
    referenceIntegrity,
    taskLifecycle,
    squashMergeHistory,
  ],
  // The baseline skills — general engineering practice every project's work
  // can call for, whatever its technology — bundled under skills/ in this pack's
  // own tree and mounted wherever basics is declared (which --init seeds
  // everywhere). When one stops being a baseline activity, move its directory to
  // the pack whose projects need it and move this line with it (#385 moved the
  // git/GitHub and Claudinite-lifecycle skills out).
  //
  // The baseline scheduled task every repo runs — `update`, the per-repo
  // self-refresh — lives in this pack's `tasks/update/`, discovered by the
  // scheduler's filesystem scan (engine/scheduler/discover.mjs), not declared
  // here. Being in basics — declared everywhere — makes it universal.
  skills: [
    'authoring-agent-docs',
    'bug-investigation',
    'bump-version',
    'file-placement',
    'repo-text-sweeps',
    'writing-tests',
  ],
};

